// Infinite tunnel — cosine palette, slow rotation
uniform float uSpeed;    // @param 0.6 0 3
uniform float uRotate;   // @param 0.08 -1 1
uniform float uDensity;  // @param 6.0 1 20
uniform float uSegments; // @param 8.0 2 24
uniform float uGlow;     // @param 1.0 0 3

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  p = rot(iTime * uRotate) * p;

  float r = max(length(p), 1e-3);
  float a = atan(p.y, p.x) / 6.28318;           // -0.5..0.5
  float z = 0.3 / r + iTime * uSpeed;           // depth along the tunnel

  float seg = floor(uSegments + 0.5);           // integer keeps the seam invisible
  float ringWave = cos(6.28318 * z * uDensity * 0.25);
  float segWave  = cos(6.28318 * a * seg);
  float tiles = 0.55 + 0.45 * ringWave * segWave;

  // thin bright seams between tiles
  float ringLine = smoothstep(0.92, 1.0, abs(ringWave));
  float segLine  = smoothstep(0.96, 1.0, abs(segWave));
  float lines = max(ringLine, segLine);

  vec3 col = palette(z * 0.12 + 0.08 * cos(6.28318 * a * 3.0),
                     vec3(0.5), vec3(0.5), vec3(1.0), vec3(0.0, 0.33, 0.67));
  col *= tiles;
  col += lines * 0.35 * col;

  // depth fog toward the vanishing point, plus a soft core glow
  float fog = smoothstep(0.0, 0.35, r);
  col *= fog;
  col += uGlow * 0.025 / r * palette(z * 0.12 + 0.5,
                     vec3(0.5), vec3(0.5), vec3(1.0), vec3(0.0, 0.33, 0.67));

  col = 1.0 - exp(-col * 1.4);                  // gentle tone map
  float vig = 1.0 - 0.35 * dot(p, p);
  fragColor = vec4(col * vig, 1.0);
}
